import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MarcheService } from '../../services/marche.service';

@Component({
  selector: 'app-marche-form',
  templateUrl: './marche-form.component.html',
  styleUrls: ['./marche-form.component.scss']
})
export class MarcheFormComponent implements OnInit {
  marcheForm: FormGroup;
  isEditMode = false;
  marcheId: number | null = null;
  isLoading = false;
  typeOptions = [
    { value: 'PRESTATION_SERVICE', label: 'Prestation de service' },
    { value: 'PRESTATION_INTELLECTUELLE', label: 'Prestation intellectuelle' },
    { value: 'FOURNITURE', label: 'Fourniture' },
    { value: 'TRAVAUX', label: 'Travaux' },
    { value: 'AUTRE', label: 'Autre' }
  ];
  statutOptions = [
    { value: 'EN_ATTENTE', label: 'En attente' },
    { value: 'ACTIF', label: 'Actif' },
    { value: 'ARCHIVE', label: 'Archivé' },
    { value: 'ANNULE', label: 'Annulé' }
  ];

  constructor(private fb: FormBuilder, private marcheService: MarcheService, private route: ActivatedRoute, private router: Router) {
    this.marcheForm = this.fb.group({
      reference: ['', Validators.required],
      objet: ['', Validators.required],
      type: ['', Validators.required],
      service: ['', Validators.required],
      statut: ['EN_ATTENTE'],
      montant: [null, Validators.required],
      description: [''],
      region: [''],
      departement: [''],
      commune: ['']
    });
  }

  ngOnInit(): void {
    this.route.params.subscribe(params => {
      if (params['id']) {
        this.isEditMode = true;
        this.marcheId = +params['id'];
        this.loadMarche(this.marcheId);
      }
    });
  }

  loadMarche(id: number): void {
    this.marcheService.getMarcheById(id).subscribe({
      next: (marche) => this.marcheForm.patchValue(marche),
      error: (error) => { console.error(error); alert('Erreur chargement'); this.router.navigate(['/marches']); }
    });
  }

  onSubmit(): void {
    if (this.marcheForm.valid) {
      this.isLoading = true;
      const formValue = this.marcheForm.value;
      const marche = {
        reference: formValue.reference,
        objet: formValue.objet,
        type: formValue.type || 'AUTRE',
        service: formValue.service,
        statut: formValue.statut || 'EN_ATTENTE',
        montant: formValue.montant,
        description: formValue.description || '',
        region: formValue.region || '',
        departement: formValue.departement || '',
        commune: formValue.commune || '',
        titulaire: 'Non spécifié',
        sourceFinancement: 'Budget National',
        duree: '12 mois',
        dateCreation: new Date().toISOString()
      };
      if (this.isEditMode && this.marcheId) {
        this.marcheService.updateMarche(this.marcheId, marche).subscribe({
          next: () => { this.isLoading = false; this.router.navigate(['/marches']); },
          error: (error) => { this.isLoading = false; console.error(error); alert('Erreur mise à jour'); }
        });
      } else {
        this.marcheService.createMarche(marche).subscribe({
          next: () => { this.isLoading = false; this.router.navigate(['/marches']); },
          error: (error) => { this.isLoading = false; console.error(error); alert('Erreur création'); }
        });
      }
    }
  }
  goBack(): void { this.router.navigate(['/marches']); }
}
<div class="marche-form-container">
  <div class="form-header">
    <h2>{{ isEditMode ? '✏️ Éditer' : '📝 Nouveau Marché' }}</h2>
    <button class="btn btn-secondary" (click)="goBack()">← Retour</button>
  </div>
  <form [formGroup]="marcheForm" (ngSubmit)="onSubmit()">
    <div class="form-grid">
      <div class="form-group"><label>📌 Référence *</label><input type="text" formControlName="reference" placeholder="M-2024-001" class="form-control"></div>
      <div class="form-group"><label>📝 Objet *</label><input type="text" formControlName="objet" placeholder="Titre" class="form-control"></div>
      <div class="form-group"><label>📂 Type *</label><select formControlName="type" class="form-control"><option value="">Sélectionnez</option><option *ngFor="let opt of typeOptions" [value]="opt.value">{{ opt.label }}</option></select></div>
      <div class="form-group"><label>🏢 Service *</label><input type="text" formControlName="service" placeholder="Service" class="form-control"></div>
      <div class="form-group"><label>📊 Statut</label><select formControlName="statut" class="form-control"><option *ngFor="let opt of statutOptions" [value]="opt.value">{{ opt.label }}</option></select></div>
      <div class="form-group"><label>💰 Montant (FCFA) *</label><input type="number" formControlName="montant" placeholder="0" class="form-control"></div>
      <div class="form-group full-width"><label>📄 Description</label><textarea formControlName="description" rows="3" class="form-control"></textarea></div>
      <div class="form-group"><label>🗺️ Région</label><input type="text" formControlName="region" placeholder="Région" class="form-control"></div>
      <div class="form-group"><label>📍 Département</label><input type="text" formControlName="departement" placeholder="Département" class="form-control"></div>
      <div class="form-group full-width"><label>🏘️ Commune</label><input type="text" formControlName="commune" placeholder="Commune" class="form-control"></div>
    </div>
    <div class="form-actions">
      <button type="button" class="btn btn-secondary" (click)="goBack()">Annuler</button>
      <button type="submit" class="btn btn-primary" [disabled]="marcheForm.invalid || isLoading">{{ isLoading ? '⏳...' : (isEditMode ? 'Mettre à jour' : 'Créer') }}</button>
    </div>
  </form>
</div>
